import { RendererCanvas3DWireframe } from "./renderer";
import { getSlider, getCheckBox } from './renderer/util'

import { NURBSCurve, Vector3 } from './NURBS/Curve';

export class Solution {
  public div: HTMLElement;
  public renderer: RendererCanvas3DWireframe;
  public vecs = [];
  public cps = [];
  public pts = [];
  public lns = [];
  public circle = [];
  public polylines = [];
  public t = 0.0;
  public tVal = 0.0;
  curve;
  N = 10;
  degree = 3;
  constructor(id: string) {
    this.div = document.getElementById(id);

    const divUI = document.createElement('div');
    divUI.style.position = 'absolute';
    this.div.appendChild(divUI);

    const slider = getSlider("N", 1, 100);
    slider.slider.defaultValue = `${this.N}`
    slider.slider.addEventListener("input", (e: Event) => {
      // get input value
      const value = +(e.target as HTMLInputElement).value;
      console.log(slider.slider.value);
      this.N = value;
      this.removeAll();
      this.init();
    });
    divUI.appendChild(slider.div);

    const slider2 = getSlider("Degree", 1, 5);
    slider2.slider.defaultValue = `${this.degree}`
    slider2.slider.addEventListener("input", (e: Event) => {
      // get input value
      const value = +(e.target as HTMLInputElement).value;
      console.log(slider2.slider.value);
      this.degree = value;
      this.removeAll();
      this.init();
    });
    divUI.appendChild(slider2.div);

    let checkBox = getCheckBox('show frame')
    checkBox.checkBox.defaultChecked = false
    checkBox.checkBox.onchange = () => {
      this.renderer.showFrame = checkBox.checkBox.checked;
      console.log(checkBox.checkBox.checked)
    }
    divUI.appendChild(checkBox.div);
    
    let checkBox2 = getCheckBox('show vertex')
    checkBox2.checkBox.defaultChecked = true
    checkBox2.checkBox.onchange = () => {
      if (checkBox2.checkBox.checked === true) {
          this.renderer.showPoint = true;
      } else {
          this.renderer.showPoint = false;
      }
    }
    divUI.appendChild(checkBox2.div);

    const slider3 = getSlider("t", 0, 100);
    slider3.slider.defaultValue = `${this.N}`
    slider3.slider.addEventListener("input", (e: Event) => {
      // get input value
      const value = +(e.target as HTMLInputElement).value;
      console.log(slider3.slider.value) ;
      this.tVal = value * 0.01;
      this.removeAll();
      this.init();
    });
    divUI.appendChild(slider3.div);

    this.renderer = new RendererCanvas3DWireframe(id);
    this.renderer.pts = this.pts;
    this.renderer.vecs = this.vecs;
    this.renderer.cps = this.cps;
    this.renderer.circle = this.circle;
    this.renderer.polylines = this.polylines

    this.init();
    this.update();
    this.render();
  }
  public init() {
    const controlPoints = [
      new Vector3(-60, 30, 0),
      new Vector3(-40, -30, 0),
      new Vector3(10, 80, 0),
      new Vector3(160, 20, 0),
      new Vector3(-30, 30, 0),
      new Vector3(0, -80, 0),
      new Vector3(80, -120, 0),
      // new Vector3(30, 160, 0),
      // new Vector3(30, 160, 0),

      // new Vector3(-0, -80, -50),
      // new Vector3(-30, 30, -40),
      // new Vector3(30, 30, 10),
      // new Vector3(-30, 30, 20),


      // new Vector3(20, 20, 0),
      // new Vector3(-14, 24, 10),
      // new Vector3(-30, -30, -10),
      // new Vector3(-30, -30, -10),

      // new Vector3(-10, 20, 5),
      // new Vector3(10, 20, 0),
      // new Vector3(30, -20, -5),
      // new Vector3(0, 0, 0),
      // new Vector3(10, 10, 2),
      // new Vector3(20, -10, 0),
      // new Vector3(30, 0, 10),
    ];

    this.cps.push(...controlPoints);

    // ];

    const curve = new NURBSCurve(controlPoints, this.degree, false);
    const interval = 1.0 / this.N;
    // 여러 t 값에서 이동좌표계 테스트
    for (let t = 0; t <= 1; t += interval) {
      console.log(`\nAt t = ${t.toFixed(1)}:`);
      const p = curve.evaluate(t);
      const frame = curve.movingFrame(t);

      const cou = curve.derivative(t)

      this.pts.push(p);
      this.polylines.push(p);

      const vNor = new Vector3(p.x + frame.normal.x, p.y + frame.normal.y, p.z + frame.normal.z)

      // this.vecs.push([p, (Vector3.add(cou, p), 1)]);
      // this.vecs.push([p, Vector3.add(p, Vector3.scale(cou, 5))]);
      this.vecs.push([p, Vector3.add(p, Vector3.scale(frame.tangent, 5))]);
      this.vecs.push([p, Vector3.add(p, Vector3.scale(frame.normal, 5))]);
      this.vecs.push([p, Vector3.add(p, Vector3.scale(frame.binormal, 5))]);
      // this.vecs.push([p, frame.tangent]);
      // this.vecs.push([p, frame.binormal]);

      // console.log("Tangent:", frame.tangent);
      // console.log("Normal:", frame.normal);
      // console.log("Binormal:", frame.binormal);

      // 정규직교성 검증
      const t_dot_n =
        frame.tangent.x * frame.normal.x +
        frame.tangent.y * frame.normal.y +
        frame.tangent.z * frame.normal.z;

      // console.log("T·N should be ~0:", t_dot_n);
    }
    this.curve = curve;

    console.log(this.vecs);


   

    const tVal = this.tVal
    const p = curve.evaluate(tVal);
    const frame = curve.movingFrame(tVal);
    const r = curve.osculatingCircleRadius(tVal);

    const pp = Vector3.subtract(p, Vector3.scale(frame.binormal, r))
    
    // const biNor = Vector3.scale(frame.binormal, -1)
    // const pp = Vector3.add(p, Vector3.scale(biNor, r))

    // console.log(r, pp)

    this.circle.push(pp)
    this.circle.push(r)

    // const pts = []
    // for(let i = 0; i < 100; ++i) {
    //   const tval = i * 0.01
    //   const vv = curve.evaluate(tval)
    //   pts.push(vv)
    // }
    // this.pts.push(...pts);
  }
  public removeAll(){
    this.cps.length = 0;
    this.pts.length = 0;
    this.vecs.length = 0;
    this.circle.length = 0;
    this.polylines.length = 0;
  }
  public update() {
    for (let i = 0; i < this.pts.length; ++i) {
      // const offset = Math.cos((this.pts[i].x + this.pts[i].y) * this.t) * 2
      // this.pts[i].z+= offset
      // this.pts[i].z = Math.cos(i * this.t * 0.1)
    }

    // console.log(this.pts)

    this.t += 0.01;
  }
  public render() {
    requestAnimationFrame(() => {
      this.render();
    });
    this.update();
    this.renderer.render();
  }
  public destroy() {
    // this.renderer.destroy();
    try {
      while (this.div && this.div.lastElementChild) {
        const lastChild = this.div.lastElementChild as Node;
        this.div.removeChild(lastChild);
      }
    } catch (error) {
      console.error("Error removing child elements:", error);
    }
  }
}
